examples:
可抽象表示为：
```cpp
class BaseStatic {
public:
    static void beStatic();
};

class DerivedStatic : public BaseStatic {
public:
    static void beStatic();
};

DerivedStatic d;
BaseStatic& ref = d;
d.beStatic();    // 按 DerivedStatic 的编译期类型调用 DerivedStatic::beStatic()
ref.beStatic();  // 按 BaseStatic& 的编译期类型调用 BaseStatic::beStatic()
```
